export default {"html":"<aside class=\"msg message\"><span class=\"msg-symbol\">!</span><div class=\"msg-content\"><p data-line=\"1\" class=\"code-line\">httpResource is currently commented as <code>Beta</code>. If you use it, remember it is still an experimental API.</p>\n</div></aside>\n<p data-line=\"4\" class=\"code-line\">httpResource is convenient. It is Signal-based and re-runs the request whenever Signals used inside the request change. Personally, I like <code>Resource.reload()</code>. Most Angular users probably routed HTTP through services with code like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"6\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Injectable</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleService</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // When handling the request with a Promise</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  getDataPromise</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">id</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Promise</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt; {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#B392F0\"> firstValueFrom</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.#http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'example/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> id));</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // Observable-based</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  getDataObservable</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">id</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Observable</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt; {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.#http.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'example/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#E1E4E8\"> id);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"23\" class=\"code-line\">Whether I reflected that in the template with the <code>async</code> pipe or assigned it to a component property, it was familiar code for a long time. Now I can write it like this:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"25\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Injectable</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleService</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // When handling the request with a Promise</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  getData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">id</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">string</span><span style=\"color:#E1E4E8\">&gt;)</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> HttpResourceRef</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt; {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt;(environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'example/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">());</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"37\" class=\"code-line\">I bind it directly on the component:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"39\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExamplePage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> id</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> input.</span><span style=\"color:#B392F0\">required</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #exampleService</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ExampleService);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> dataResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.#exampleService.</span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.id);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"48\" class=\"code-line\">The main thing to watch is passing the Signal itself as an argument, not unwrapping its value. Requests are handled by Signal values without lifecycle hooks—simple and very nice. I recommend trying it.</p>\n<p data-line=\"50\" class=\"code-line\">With Ionic Angular, the code looks like this (for the ViewDidEnter property, see <a href=\"https://zenn.dev/rdlabo/articles/bb03d724d33831\" target=\"_blank\" rel=\"noopener noreferrer\">https://zenn.dev/rdlabo/articles/bb03d724d33831</a>):</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"52\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExamplePage</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> id</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> input.</span><span style=\"color:#B392F0\">required</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">number</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> el</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ElementRef);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #didEnter</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> toSignal</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#B392F0\">createDidEnter</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.el));</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #exampleService</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ExampleService);</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> dataResource</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.#exampleService.</span><span style=\"color:#B392F0\">getData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.#didEnter, </span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.id);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"63\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Injectable</span><span style=\"color:#E1E4E8\">({</span><span style=\"color:#F97583\">...</span><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> ExampleService</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">  readonly</span><span style=\"color:#FFAB70\"> #http</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(HttpClient);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  </span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  getData</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">didEnter</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">boolean</span><span style=\"color:#E1E4E8\">&gt;, </span><span style=\"color:#FFAB70\">id</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> Signal</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">string</span><span style=\"color:#E1E4E8\">&gt;)</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> HttpResourceRef</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">Data</span><span style=\"color:#E1E4E8\">&gt; {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">    return</span><span style=\"color:#B392F0\"> httpResource</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#B392F0\">IMovie</span><span style=\"color:#E1E4E8\">[]&gt;(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#B392F0\">didEnter</span><span style=\"color:#E1E4E8\">()) {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">        return</span><span style=\"color:#79B8FF\"> undefined</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      return</span><span style=\"color:#E1E4E8\"> environment.api </span><span style=\"color:#F97583\">+</span><span style=\"color:#9ECBFF\"> 'example/'</span><span style=\"color:#F97583\"> +</span><span style=\"color:#B392F0\"> id</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"79\" class=\"code-line\">Compared to before, I can write this much more simply. The API is still experimental, but give it a try!</p>\n","headings":[]} as const;
